}

.product-card.out-of-stock {
    opacity: 0.7;
}

.product-image-placeholder {
    height: 180px;
    font-size: 0.9rem;
    border-bottom: 1px solid #dee2e6;
    overflow: hidden;
    text-align: center;
    padding: 1rem;
}

.star-rating {
    color: #f5a623;
    font-size: 1.1rem;
    letter-spacing: 2px;
}

