{"path": "/tmp/sv-baf7f6484f7f4103804b52a8cf46693f/Components/Catalog/ProductCard.razor", "file_text": "<div class="product-card card h-100 @(Product.InStock ? "" : "out-of-stock")" @onclick="HandleCardClick">
    <div class="product-image-placeholder d-flex align-items-center justify-content-center bg-light" role="img" aria-label="@Product.Name">
        <span class="text-muted">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h5 class="card-title text-truncate" title="@Product.Name">@Product.Name</h5>
        <p class="card-text fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <p class="card-text mb-2 star-rating" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">@GetStarDisplay()</p>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private string GetStarDisplay()
    {
        int fullStars = (int)Math.Round(Product.Rating);
        return new string('★', fullStars) + new string('☆', 5 - fullStars);
    }
}
"}

