@@ -1,0 +1,163 @@
+@page "/catalog"
+@using sv_baf7f6484f7f4103804b52a8cf46693f.Components.Catalog
+@rendermode InteractiveServer
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h1 class="mb-4">Product Catalog</h1>
+
+<div class="catalog-layout d-flex gap-4">
+    <aside class="catalog-sidebar">
+        <CatalogFilters Categories="categories"
+                        OnFiltersApplied="HandleFiltersApplied"
+                        OnFiltersCleared="HandleFiltersCleared" />
+    </aside>
+
+    <main class="catalog-main flex-grow-1">
+        @if (errorMessage is not null)
+        {
+            <div class="alert alert-danger" role="alert">
+                <strong>Error:</strong> @errorMessage
+            </div>
+        }
+        else if (isLoading)
+        {
+            <div class="d-flex justify-content-center align-items-center py-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading products...</span>
+                </div>
+                <span class="ms-3">Loading products...</span>
+            </div>
+        }
+        else if (result is not null && result.Items.Count == 0)
+        {
+            <div class="alert alert-info" role="alert">
+                No products match your filters. Try adjusting your criteria or
+                <button class="btn btn-link p-0 align-baseline" @onclick="HandleFiltersCleared">clearing all filters</button>.
+            </div>
+        }
+        else if (result is not null)
+        {
+            <CatalogToolbar SortBy="@sortBy"
+                            TotalCount="result.TotalCount"
+                            Page="result.Page"
+                            PageSize="result.PageSize"
+                            OnSortChanged="HandleSortChanged" />
+
+            <ProductGrid Products="result.Items"
+                         OnProductSelected="HandleProductSelected"
+                         OnAddToCart="HandleAddToCart" />
+
+            <CatalogPagination Page="result.Page"
+                               TotalPages="totalPages"
+                               OnPageChanged="HandlePageChanged" />
+        }
+    </main>
+</div>
+
+@code {
+    private List<string> categories = [];
+    private PagedResult<Product>? result;
+    private ProductFilter currentFilter = new(null, null, null, false);
+    private string sortBy = "price_asc";
+    private int currentPage = 1;
+    private const int PageSize = 12;
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    private int totalPages => result is null || result.PageSize == 0
+        ? 0
+        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadDataAsync();
+    }
+
+    private async Task LoadDataAsync()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);
+
+            await Task.WhenAll(categoriesTask, productsTask);
+
+            categories = await categoriesTask;
+            result = await productsTask;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load products. Please try again. ({ex.Message})";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task SearchAsync()
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, PageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load products. Please try again. ({ex.Message})";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task HandleFiltersApplied(ProductFilter filter)
+    {
+        currentFilter = filter;
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleFiltersCleared()
+    {
+        currentFilter = new ProductFilter(null, null, null, false);
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandleSortChanged(string newSortBy)
+    {
+        sortBy = newSortBy;
+        currentPage = 1;
+        await SearchAsync();
+    }
+
+    private async Task HandlePageChanged(int page)
+    {
+        currentPage = page;
+        await SearchAsync();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Cart logic to be implemented by parent or a cart service
+        return Task.CompletedTask;
+    }
+}
+

